Suppose $n$ integers are placed in a circle such that each of the following conditions is satisfied:
\begin{itemize}
\item at least one of the integers is $0$;
\item each pair of adjacent integers differs by exactly $1$; and
\item the sum of the integers is exactly $24$.
\end{itemize}
Compute the smallest value of $n$ for which this is possible.

I think the matchFound variable should actually look more like this.

var matchFound = bonuses.filter(function(element1) {
 return $(myArray).not(element1).some(function(element2) {
 var title1 = $(element1).attr('title');
 var title2 = $(element2).attr('title');

 if (title1 && title2) {
 var num1 = parseInt(title1.match(regex)[0]); // extract the first number from title1
 var num2 = parseInt(title2.match(regex)[0]); // extract the first number from title2
 var hasPerc1AndB1 = num1 >= perc1 && title1.includes(b1);
 var hasPerc2AndB2 = num2 >= perc2 && title2.includes(b2);
 var hasPerc2AndB2InDifferentElements = num1 >= perc2 && title1.includes(b2) && num2 >= perc1 && title2.includes(b1);
 return (hasPerc1AndB1 && hasPerc2AndB2) || hasPerc2AndB2InDifferentElements;
 }
 return false;
 });
 });

